--
-- Table structure for table `data_management_connections`
--

DROP TABLE IF EXISTS `data_management_connections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `data_management_connections` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `db_type_id` int NOT NULL COMMENT 'MySql,Postgres,SqlServer,Sqlite',
  `host` varchar(100) NOT NULL,
  `host_port` int NOT NULL,
  `db_name` varchar(100) NOT NULL,
