/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `education_grades_subjects` (
  `id` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hours_required` decimal(5,2) DEFAULT NULL,
  `visible` int NOT NULL DEFAULT '1',
  `auto_allocation` int NOT NULL DEFAULT '1',
  `education_grade_id` int NOT NULL COMMENT 'links to education_grades.id',
  `education_subject_id` int NOT NULL COMMENT 'links to education_subjects.id',
  `requirement` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `result_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Assessments',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`education_grade_id`,`education_subject_id`),
  KEY `education_grade_id` (`education_grade_id`),
  KEY `education_subject_id` (`education_subject_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  CONSTRAINT `educa_grade_subje_fk_edu_gra_id` FOREIGN KEY (`education_grade_id`) REFERENCES `education_grades` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `educa_grade_subje_fk_edu_sub_id` FOREIGN KEY (`education_subject_id`) REFERENCES `education_subjects` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of subjects linked to specific education grade';
