LL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 all_total ,CASE WHEN genders.id = 1 THEN SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 END all_male ,CASE WHEN genders.id = 2 THEN SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 END all_female FROM assessment_item_results INNER JOIN ( SELECT assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id ,MAX(assessment_item_results.created) latest_created FROM assessment_item_results GROUP BY assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id) latest_grades ON latest_grades.student_id = assessment_item_results.student_id AND latest_grades.assessment_id = assessment_item_results.assessment_id AND latest_grades.education_subject_id = assessment_item_results.education_subject_id AND latest_grades.assessment_period_id = assessment_item_results.assessment_period_id AND latest_grades.latest_created = assessment_item_results.created LEFT JOIN assessment_grading_options ON assessment_grading_options.id = assessment_item_results.assessment_grading_option_id LEFT JOIN assessment_grading_types ON assessment_grading_types.id = assessment_grading_options.assessment_grading_type_id INNER JOIN assessment_periods ON assessment_periods.id = assessment_item_results.assessment_period_id AND assessment_periods.assessment_id = assessment_item_results.assessment_id INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id INNER JOIN institutions ON institutions.id = assessment_item_results.institution_id INNER JOIN 