tive_id INNER JOIN security_users ON security_users.id = assessment_item_results.student_id INNER JOIN genders ON genders.id = security_users.gender_id LEFT JOIN ( SELECT user_nationalities.id student_default_nationality_id ,user_nationalities.security_user_id ,nationalities.name student_default_nationality_name FROM user_nationalities INNER JOIN nationalities ON nationalities.id = user_nationalities.nationality_id WHERE user_nationalities.preferred = 1 GROUP BY user_nationalities.security_user_id ) AS student_nationalities ON student_nationalities.security_user_id = security_users.id LEFT JOIN ( SELECT user_identities.security_user_id ,GROUP_CONCAT(user_identities.id) student_default_identity_id ,GROUP_CONCAT(identity_types.name) student_default_identity_type ,GROUP_CONCAT(user_identities.number) student_default_identity_number FROM user_identities INNER JOIN identity_types ON identity_types.id = user_identities.identity_type_id WHERE identity_types.default = 1 GROUP BY user_identities.security_user_id ) AS student_identities ON student_identities.security_user_id = security_users.id INNER JOIN education_grades ON education_grades.id = assessment_item_results.education_grade_id INNER JOIN education_subjects ON education_subjects.id = assessment_item_results.education_subject_id GROUP BY education_subjects.id ,security_users.id;','week',1,NULL,NULL,1,'2023-02-08 08:22:38'),(58,'summary_institution_nationalities_create','CREATE TABLE IF NOT EXISTS `summary_institution_nationalities`( `academic_period_id` int(11) NOT NULL, `academic_period_name` varchar(50) NOT NULL, `institution_id` int(11) NOT NULL, `institution_code` varchar(50) NOT NULL, `nationality_id` int(11) NULL, `nationality_name` varchar(50) NULL, `total_students` int(9) NOT NULL, `total_students_female` int(9) NOT NULL, `total_students_male` int(9) NOT NULL) ENGINE = InnoDB DEFAULT CHARSET = utf8;','week',1,NULL,NULL,1,'2023-04-27 10:02:31'),(59,'summary_institution_nationalities_truncate','TRUNCATE summar