ector_name ,main_query.education_system_id ,main_query.education_system_name ,main_query.education_level_isced_id ,main_query.education_level_isced_name ,main_query.education_level_isced_level ,COUNT(DISTINCT(main_query.institution_id)) count_total_instiutions ,IFNULL(COUNT(DISTINCT(electricity_info.institution_id)),0) count_electricity_institutions ,IFNULL(COUNT(DISTINCT(computer_info.institution_id)),0) count_computer_institutions ,IFNULL(COUNT(DISTINCT(teaching_computer_info.institution_id)),0) count_teaching_computer_institutions ,IFNULL(COUNT(DISTINCT(internet_info.institution_id)),0) count_internet_institutions ,IFNULL(COUNT(DISTINCT(toilet_info.institution_id)),0) count_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_toilet_info.institution_id)),0) count_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_toilet_info.institution_id)),0) count_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_improved_toilet_info.institution_id)),0) count_improved_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_toilet_info.institution_id)),0) count_in_use_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_improved_toilet_info.institution_id)),0) count_in_use_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_single_sex_toilet_info.institution_id)),0) count_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_in_use_single_sex_toilet_info.institution_id)),0) count_improved_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(drinking_water_info.institution_id)),0) count_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(available_drinking_water_info.institution_id)),0) count_functional_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(handwashing_facility_info.institution_id)),0) count_handwashing_facility_institutions ,IFNULL(COUNT(DISTINCT(accessible_rooms_info.institution_id)),0) count_accessible_room_institutions FROM ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,education_level_isced.isced_level education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id INNER JOIN ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,MAX(education_level_isced.isced_level) education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,institutions.id) max_isced_level ON max_isced_level.academic_period_id = academic_periods.id AND max_isced_level.institution_sector_id = institution_sectors.id AND max_isced_level.institution_id = institutions.id AND max_isced_level.education_level_isced_level = education_level_isced.isced_level WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,institutions.id ) main_query LEFT JOIN ( SELECT infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id FROM infrastructure_utility_electricities GROUP BY infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id ) electricity_info ON electricity_info.academic_period_id = main_query.academic_period_id AND electricity_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_assets.institution_id FROM institution_assets INNER JOIN asset_types ON asset_types.id = institution_assets.asset_type_id WHERE institution_assets.asset_status_id = 1 AND (asset_types.name LIKE \'%Computer%\' OR asset_types.name LIKE \'%Laptop%\') GROUP BY institution_assets.institution_id ) computer_info ON computer_info.institution_id = main_query.institution_id LEFT J