re_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) in_use_single_sex_toilet_info ON in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) improved_in_use_single_sex_toilet_info ON improved_in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND improved_in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) drinking_water_info ON drinking_water_info.academic_period_id = main_query.academic_period_id AND drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters INNER JOIN infrastructure_wash_water_functionalities ON infrastructure_wash_water_functionalities.id = infrastructure_wash_waters.infrastructure_wash_water_functionality_id WHERE infrastructure_wash_water_functionalities.name NOT LIKE \'%Not Functional%\' GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) available_drinking_water_info ON available_drinking_water_info.academic_period_id = main_query.academic_period_id AND available_drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id FROM infrastructure_wash_hygienes INNER JOIN infrastructure_wash_hygiene_types ON infrastructure_wash_hygiene_types.id = infrastructure_wash_hygienes.infrastructure_wash_hygiene_type_id WHERE infrastructure_wash_hygiene_types.name NOT LIKE \'%Not Available%\' GROUP BY infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id ) handwashing_facility_info ON handwashing_facility_info.academic_period_id = main_query.academic_period_id AND handwashing_facility_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id FROM institution_rooms WHERE institution_rooms.accessibility = 1 GROUP BY institution_rooms.academic_period_id ,institution_rooms.institution_id ) accessible_rooms_info ON accessible_rooms_info.academic_period_id = main_query.academic_period_id AND accessible_rooms_info.institution_id = main_query.institution_id GROUP BY main_query.academic_period_id ,main_query.institution_sector_id ,main_query.education_level_isced_id;','week',1,NULL,NULL,1,'2023-04-27 10:02:31'),(67,'delete_security_users_openemis_no','DELETE FROM security_users_openemis_no WHERE created < DATE_SUB(NOW(), INTERVAL 1 DAY);','day',1,NULL,NULL,1,'2025-11-12 00:00:00'),(69,'summary_student_attendances_truncate','TRUNCATE summary_student_attendances;','day',1,NULL,NULL,1,'2026-05-15 05:47:03'),(70,'summary_student_attendances_insert','SET TRANSACTION ISOLATION LEVEL READ COMMITTED; START TRANSACTION; INSERT IGNORE INTO summary_student_attendances SELECT count_date_class_students.academic_period_id, academic_period_name, count_date_class_students.institution_id, institutions.code institution_code, institutions.name institution_name, eg.id education_grade_id, eg.code education_grade_code, eg.name education_grade_name, count_date_class_students.institution_class_id class_id, ic.name class_name, count_date_class_students.dates attendance_date, count_date_class_students.period_id, count_date_class_students.period_name, IF(samr.subject_id IS NULL,\'0\',samr.subject_id) subject_id, IF(samr.subject_id IS NOT NULL,IF(samr.subject_id=0,\'0\',subj.name),\'0\') AS subject_name, female_count, male_count, total_count, IF(samr.institution_id IS NOT NULL, 1, 0) marked_attendance, IF(samr.institution_id IS NULL, 1, 0) unmarked_attendance, IF(samr.institution_id IS NOT NULL, IF(no_scheduled_class = 1, \'0\',female_count - IFNULL(absent_female, 0)), 0) AS present_female_count, IF(samr.institution_id IS NOT NULL, IF(no_scheduled_class = 1, \'0\',male_count - IFNULL(absent_male, 0)), 0) AS present_male_count, IF(samr.institution_id IS NOT NULL, IF(no_scheduled_class = 1, \'0\',total_count - IFNULL(absent_total, 0)), 0) AS present_total_count, IF(no_scheduled_class = 1, 0, IFNULL(absent_female, 0)) AS absent_female_count, IF(no_scheduled_class = 1, 0, IFNULL(absent_male, 0)) AS absent_male_count, IF(no_scheduled_class = 1, 0, IFNULL(absent_total, 0)) AS absent_total_count, IF(late_female IS NULL,0, late_female) AS late_female_count, IF(late_male IS NULL,0, late_male) AS late_male_count, IF(late_total IS NULL,0, late_total) AS late_total_count, 0, 0, 0, 0, 0, 0, CURRENT_TIMESTAMP FROM(SELECT a.*, period_id, period_name FROM(SELECT ics.institution_id, ics.institution_class_id, apd.academic_period_id, apd.academic_period_name, icg.education_grade_id, apd.attendance_date AS dates, SUM(CASE WHEN su.gender_id = 2 THEN 1 ELSE 0 END) AS female_count, SUM(CASE WHEN su.gender_id = 1 THEN 1 ELSE 0 END) AS male_count, SUM(CASE WHEN su.gender_id IN(1, 2) THEN 1 ELSE 0 END) AS total_count FROM (SELECT ap.id AS academic_period_id, ap.name AS academic_period_name, DATE_ADD(ap.start_date, INTERVAL seq.n DAY) AS attendance_date, WEEKDAY(DATE_ADD(ap.start_date, INTERVAL seq.n DAY)) + 1 AS day_of_week, CAST(IF(TRIM(IFNULL(fdow.value, \'\')) = \'\', \'1\', fdow.value) AS SIGNED) AS first_day_of_week, CAST(IF(TRIM(IFNULL(dpw.value, \'\')) = \'\', \'5\', dpw.value) AS SIGNED) AS days_per_week FROM academic_periods ap INNER JOIN config_items fdow ON fdow.code = \'first_day_of_week\' INNER JOIN config_items dpw ON dpw.code = \'days_per_week\' INNER JOIN (SELECT a.n + b.n * 10 + c.n * 100 + d.n * 1000 AS n FROM (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d) seq ON seq.n <= DATEDIFF(LEAST(ap.end_date, CURDATE()), ap.start_date) WHERE ap.parent_id <> 0 AND ap.start_date <= CURDATE() AND MOD((WEEKDAY(DATE_ADD(ap.start_date, INTERVAL seq.n DAY)) + 1 - CAST(IF(TRIM(IFNULL(fdow.value, \'\')) = \'\', \'1\', fdow.value) AS SIGNED) + 7), 7) < CAST(IF(TRIM(IFNULL(dpw.value, \'\')) = \'\', \'5\', dpw.value) AS SIGNED)) apd INNER JOIN institution_class_students ics ON ics.academic_period_id = apd.academic_period_id INNER JOIN institution_class_grades icg ON icg.institution_class_id = ics.institution_class_id INNER JOIN institution_students ist ON ist.student_id = ics.student_id AND ist.education_grade_id = icg.education_grade_id INNER JOIN security_users su ON su.id = ist.student_id WHERE apd.attendance_date BETWEEN ist.start_date AND ist.end_date GROUP BY ics.institution_id, ics.institution_class_id, apd.academic_period_id, apd.academic_period_name, apd.attendance_date) a CROSS JOIN (SELECT smts.academic_period_id, smtsg.education_grade_id, smts.date_enabled, smts.date_disabled, sapdp.name AS period_name, sapdp.period AS period_id FROM student_mark_type_statuses smts INNER JOIN student_mark_type_status_grades smtsg ON smts.id = smtsg.student_mark_type_status_id INNER JOIN student_attendance_mark_types satmt ON satmt.id = smts.student_attendance_mark_type_id LEFT JOIN student_attendance_per_day_periods sapdp ON sapdp.student_attendance_mark_type_id = satmt.id) AS period_config ON a.dates BETWEEN period_config.date_enabled AND period_config.date_disabled AND a.education_grade_id = period_config.education_grade_id) AS count_date_class_students INNER JOIN institutions ON institutions.id = count_date_class_students.institution_id INNER JOIN institution_classes ic ON ic.id = count_date_class_students.institution_class_id INNER JOIN institution_class_grades icg ON icg.institution_class_id = count_date_class_students.institution_class_id INNER JOIN education_grades eg ON eg.id = icg.education_grade_id LEFT JOIN (SELECT * FROM student_attendance_marked_records WHERE no_scheduled_class = 0) samr ON samr.institution_class_id = count_date_class_students.institution_class_id AND samr.date = count_date_class_students.dates AND samr.period = count_date_class_students.period_id LEFT JOIN (SELECT d.academic_period_id, d.institution_class_id, d.education_grade_id, d.date, IF(d.period = 0, 1 ,d.period) AS period_id, d.subject_id, SUM(IF(d.absence_type_id <> 3 AND u.gender_id = 2, 1, 0)) AS absent_female, SUM(IF(d.absence_type_id <> 3 AND u.gender_id = 1, 1, 0)) AS absent_male, SUM(IF(d.absence_type_id <> 3 AND u.gender_id IN(1, 2), 1, 0)) AS absent_total, SUM(IF(d.absence_type_id = 3 AND u.gender_id = 2, 1, 0)) AS late_female, SUM(IF(d.absence_type_id = 3 AND u.gender_id = 1, 1, 0)) AS late_male, SUM(IF(d.absence_type_id = 3 AND u.gender_id IN (1, 2), 1, 0)) AS late_total FROM institution_student_absence_details d INNER JOIN security_users u ON u.id = d.student_id INNER JOIN institution_class_students ics ON ics.student_id = d.student_id AND ics.institution_class_id = d.institution_class_id GROUP BY d.date, d.institution_class_id, d.subject_id, d.period) AS count_date_class_student_absences ON count_date_class_student_absences.institution_class_id = count_date_class_students.institution_class_id AND count_date_class_student_absences.date = count_date_class_students.dates AND count_date_class_student_absences.period_id = count_date_class_students.period_id AND count_date_class_student_absences.education_grade_id = count_date_class_students.education_grade_id AND count_date_class_student_absences.academic_period_id = count_date_class_students.academic_period_id AND count_date_class_student_absences.subject_id = samr.subject_id LEFT JOIN institution_subjects subj ON subj.id = samr.subject_id WHERE academic_period_name IS NOT NULL ORDER BY count_date_class_students.dates ASC, count_date_class_students.institution_id ASC, eg.id ASC, count_date_class_students.institution_class_id ASC, samr.period ASC, samr.subject_id ASC; COMMIT;','day',1,NULL,NULL,1,'2026-05-15 05:47:03'),(71,'summary_student_attendances_update','UPDATE summary_student_attendances INNER JOIN( SELECT absence_per_student.academic_period_id, absence_per_student.education_grade_id, absence_per_student.institution_id, absence_per_student.institution_class_id, absence_per_student.date, SUM(IF(absence_per_student.student_gender_id = 2 AND absence_per_student.partial_day_absence = 1, 1, 0)) AS partial_absent_female_count, SUM(IF(absence_per_student.student_gender_id = 1 AND absence_per_student.partial_day_absence = 1, 1, 0)) AS partial_absent_male_count, SUM(IF(absence_per_student.partial_day_absence = 1, 1, 0)) AS partial_absent_total_count, SUM(IF(absence_per_student.student_gender_id = 2 AND absence_per_student.full_day_absence = 1, 1, 0)) AS full_absent_female_count, SUM(IF(absence_per_student.student_gender_id = 1 AND absence_per_student.full_day_absence = 1, 1, 0)) AS full_absent_male_count, SUM(IF(absence_per_student.full_day_absence = 1, 1, 0)) AS full_absent_total_count FROM ( SELECT count_student_absent_day.academic_period_id, count_student_absent_day.education_grade_id, count_student_absent_day.institution_id, count_student_absent_day.institution_class_id, count_student_absent_day.date, count_student_absent_day.student_id, subject_per_student.student_gender_id, count_student_absent_day.total_absences_day, marked_slots.valid_marked_slots, CASE WHEN marked_slots.valid_marked_slots > 0 AND count_student_absent_day.total_absences_day < marked_slots.valid_marked_slots THEN 1 ELSE 0 END AS partial_day_absence, CASE WHEN marked_slots.valid_marked_slots > 0 AND count_student_absent_day.total_absences_day >= marked_slots.valid_marked_slots THEN 1 ELSE 0 END AS full_day_absence FROM ( SELECT institution_student_absence_details.academic_period_id, institution_student_absence_details.date, institution_student_absence_details.institution_id, institution_student_absence_details.education_grade_id, institution_student_absence_details.institution_class_id, institution_student_absence_details.student_id, COUNT(*) AS total_absences_day FROM institution_student_absence_details INNER JOIN institution_class_students ics ON ics.student_id = institution_student_absence_details.student_id AND ics.institution_class_id = institution_student_absence_details.institution_class_id WHERE institution_student_absence_details.absence_type_id != 3 GROUP BY institution_student_absence_details.academic_period_id, institution_student_absence_details.date, institution_student_absence_details.institution_id, institution_student_absence_details.education_grade_id, institution_student_absence_details.institution_class_id, institution_student_absence_details.student_id) count_student_absent_day INNER JOIN ( SELECT institution_subject_students.student_id, institution_subject_students.institution_class_id, institution_subject_students.education_grade_id, institution_subject_students.institution_id, security_users.gender_id AS student_gender_id FROM institution_subject_students INNER JOIN security_users ON security_users.id = institution_subject_students.student_id GROUP BY institution_subject_students.student_id, institution_subject_students.institution_class_id, institution_subject_students.education_grade_id, institution_subject_students.institution_id, security_users.gender_id ) subject_per_student ON subject_per_student.student_id = count_student_absent_day.student_id AND subject_per_student.education_grade_id = count_student_absent_day.education_grade_id AND subject_per_student.institution_class_id = count_student_absent_day.institution_class_id AND subject_per_student.institution_id = count_student_absent_day.institution_id INNER JOIN ( SELECT academic_period_id, institution_id, education_grade_id, class_id, attendance_date, COUNT(*) AS valid_marked_slots FROM summary_student_attendances WHERE marked_attendance > 0 GROUP BY academic_period_id, institution_id, education_grade_id, class_id, attendance_date ) marked_slots ON marked_slots.academic_period_id = count_student_absent_day.academic_period_id AND marked_slots.institution_id = count_student_absent_day.institution_id AND marked_slots.education_grade_id = count_student_absent_day.education_grade_id AND marked_slots.class_id = count_student_absent_day.institution_class_id AND marked_slots.attendance_date = count_student_absent_day.date ) absence_per_student GROUP BY absence_per_student.academic_period_id, absence_per_student.education_grade_id, absence_per_student.institution_id, absence_per_student.institution_class_id, absence_per_student.date ) absence_summary ON absence_summary.academic_period_id = summary_student_attendances.academic_period_id AND absence_summary.education_grade_id = summary_student_attendances.education_grade_id AND absence_summary.institution_id = summary_student_attendances.institution_id AND absence_summary.institution_class_id = summary_student_attendances.class_id AND absence_summary.date = summary_student_attendances.attendance_date SET summary_student_attendances.partial_absent_female_count = absence_summary.partial_absent_female_count, summary_student_attendances.partial_absent_male