DROP TABLE IF EXISTS `staff_salaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `staff_salaries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `salary_date` date NOT NULL,
  `comment` text,
  `gross_salary` decimal(20,2) NOT NULL,
  `net_salary` decimal(20,2) NOT NULL,
  `staff_id` int NOT NULL COMMENT 'links to security_users.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `staff_id` (`staff_id`),
  CONSTRAINT `staff_salar_fk_staff_id` FOREIGN KEY (`staff_id`) REFERENCES `security_users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains all salary information of staff';
