  `modified` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tasks_status_available` (`status`,`available_at`),
  KEY `idx_tasks_task_type` (`task_type`),
  KEY `idx_tasks_source` (`source_table`,`source_id`)
