CREATE TABLE `textbooks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `author` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publisher` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `year_published` int NOT NULL,
  `ISBN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `academic_period_id` int NOT NULL COMMENT 'links to academic_period.id',
  `education_grade_id` int NOT NULL COMMENT 'links to education_grades.id',
  `education_subject_id` int NOT NULL COMMENT 'links to education_subjects.id',
  `textbook_dimension_id` int DEFAULT NULL,
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`,`academic_period_id`),
  KEY `academic_period_id` (`academic_period_id`),
  KEY `education_grade_id` (`education_grade_id`),
  KEY `education_subject_id` (`education_subject_id`),
  KEY `fk_textbook_dimensions` (`textbook_dimension_id`),
  CONSTRAINT `fk_textbook_dimensions` FOREIGN KEY (`textbook_dimension_id`) REFERENCES `textbook_dimensions` (`id`),
  CONSTRAINT `textb_fk_aca_per_id` FOREIGN KEY (`academic_period_id`) REFERENCES `academic_periods` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `textb_fk_edu_gra_id` FOREIGN KEY (`education_grade_id`) REFERENCES `education_grades` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `textb_fk_edu_sub_id` FOREIGN KEY (`education_subject_id`) REFERENCES `education_subjects` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the textbooks of all subjects';
