CREATE TABLE `training_courses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `objective` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `credit_hours` int NOT NULL,
  `duration` int NOT NULL,
  `number_of_months` int NOT NULL,
  `special_education_needs` int NOT NULL,
  `file_name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_content` longblob,
  `training_field_of_study_id` int NOT NULL COMMENT 'links to training_field_of_studies.id',
  `training_course_type_id` int NOT NULL COMMENT 'links to training_course_types.id',
  `training_course_category_id` int NOT NULL COMMENT 'links to training_course_categories.id',
  `training_mode_of_delivery_id` int NOT NULL COMMENT 'links to training_mode_of_deliveries.id',
  `training_requirement_id` int NOT NULL COMMENT 'links to training_requirements.id',
  `training_level_id` int NOT NULL COMMENT 'links to training_levels.id',
  `assignee_id` int NOT NULL DEFAULT '0' COMMENT 'links to security_users.id',
  `status_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `special_education_needs` (`special_education_needs`),
  KEY `training_field_of_study_id` (`training_field_of_study_id`),
  KEY `training_course_type_id` (`training_course_type_id`),
  KEY `training_mode_of_delivery_id` (`training_mode_of_delivery_id`),
  KEY `training_requirement_id` (`training_requirement_id`),
  KEY `training_level_id` (`training_level_id`),
  KEY `assignee_id` (`assignee_id`),
  KEY `status_id` (`status_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  KEY `training_course_category_id` (`training_course_category_id`),
  CONSTRAINT `train_cours_fk_ass_id` FOREIGN KEY (`assignee_id`) REFERENCES `security_users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_statu_id` FOREIGN KEY (`status_id`) REFERENCES `workflow_steps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_cours_categ_id` FOREIGN KEY (`training_course_category_id`) REFERENCES `training_course_categories` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_cours_type_id` FOREIGN KEY (`training_course_type_id`) REFERENCES `training_course_types` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_field_of_study_id` FOREIGN KEY (`training_field_of_study_id`) REFERENCES `training_field_of_studies` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_level_id` FOREIGN KEY (`training_level_id`) REFERENCES `training_levels` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_mode_of_deliv_id` FOREIGN KEY (`training_mode_of_delivery_id`) REFERENCES `training_mode_deliveries` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `train_cours_fk_train_requi_id` FOREIGN KEY (`training_requirement_id`) REFERENCES `training_requirements` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all training courses';
