--
-- Table structure for table `workflow_actions`
--

DROP TABLE IF EXISTS `workflow_actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workflow_actions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `action` int DEFAULT NULL COMMENT '0 -> Approve, 1 -> Reject',
  `visible` int NOT NULL DEFAULT '1',
  `comment_required` int NOT NULL DEFAULT '0',
  `allow_by_assignee` int NOT NULL DEFAULT '0',
  `event_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `workflow_step_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `next_workflow_step_id` int NOT NULL,
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `allow_by_assignee` (`allow_by_assignee`),
  KEY `next_workflow_step_id` (`next_workflow_step_id`),
  KEY `workflow_step_id` (`workflow_step_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  CONSTRAINT `workf_actio_fk_workf_step_id` FOREIGN KEY (`workflow_step_id`) REFERENCES `workflow_steps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=239 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains all actions used by different steps of any workflow';
/*!40101 SET character_set_client = @saved_cs_client */;

